#include "lsm/db.h"
#include "lsm/sstable.h"
#include "lsm/manifest.h"
#include "lsm/write_batch.h"
#include "lsm/coding.h"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <memory>
#include <numeric>
#include <random>
#include <stdexcept>
#include <thread>
#include <sys/resource.h>
using Clock=std::chrono::steady_clock;
namespace fs=std::filesystem;
using Oracle=std::map<std::string,lsm::Entry>;
double ns(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::nano>(b-a).count();}
void need(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
std::string key(size_t i){char s[17];std::snprintf(s,sizeof(s),"%016llx",static_cast<unsigned long long>(i*2));return s;}
std::string value(size_t i,size_t version){std::string s(128,'a');for(size_t j=0;j<s.size();++j)s[j]=char('!'+(i*13+version*7+j*17)%90);return s;}
std::string path(const std::string& d,uint64_t n){char s[32];std::snprintf(s,sizeof(s),"%06llu.sst",static_cast<unsigned long long>(n));return d+"/"+s;}
DBOptions options(size_t cap,size_t target=4*1024*1024){DBOptions o;o.enableWal=false;o.blockCacheCapacity=cap;o.memTableSizeLimit=1024*1024;o.targetSSTableDataSize=target;return o;}
void saveOracle(const std::string& d,const Oracle& m){std::ofstream f(d+"/oracle.bin",std::ios::binary);for(const auto& p:m){auto s=lsm::EncodeEntry(p.second);std::string n;lsm::AppendFixed32(n,s.size());f.write(n.data(),4);f.write(s.data(),s.size());}need(bool(f),"save oracle");}
Oracle loadOracle(const std::string& d){Oracle m;std::ifstream f(d+"/oracle.bin",std::ios::binary);char n[4];while(f.read(n,4)){std::string s(lsm::DecodeFixed32(n),'\0');need(bool(f.read(s.data(),s.size())),"oracle read");lsm::Entry e;need(lsm::DecodeEntry(s,e),"oracle decode");m.emplace(e.key.user_key,e);}return m;}
void verify(DB& db,const Oracle& m){for(const auto& p:m){auto v=db.Get(p.first);if(p.second.key.type==ValueType::kDeletion)need(!v,"deleted key exists");else need(v&&*v==p.second.value,"value mismatch");}need(!db.Get("ffffffffffffffff"),"missing key exists");}
struct Stats{uint64_t tables=0,bytes=0,records=0,encoded=0,tombstones=0,flushed=0,physical=0;};
Stats stats(const std::string& d,const Oracle& m,bool exact){auto mf=Manifest::Load(d+"/MANIFEST");Stats s;s.tables=mf.Tables().size();s.flushed=mf.FlushedSequence();std::map<std::string,size_t> counts;for(const auto& t:mf.Tables()){s.bytes+=t.fileSize;SSTableReader r(path(d,t.fileNumber));for(auto it=r.Begin();it.Valid();it.Next()){++s.records;s.encoded+=lsm::EncodedEntrySize({it.Key(),it.Value()});s.tombstones+=it.Key().type==ValueType::kDeletion;if(exact){auto p=m.find(it.Key().user_key);need(p!=m.end(),"unexpected key");need(p->second.key.sequence==it.Key().sequence&&p->second.key.type==it.Key().type&&p->second.value==it.Value(),"physical newest/sequence mismatch");need(++counts[it.Key().user_key]==1,"duplicate compact key");}}}if(exact)need(counts.size()==m.size(),"compact key lost");for(const auto& p:fs::directory_iterator(d))if(p.path().extension()==".sst")++s.physical;return s;}
void emitStats(const Stats& s){std::cout<<"{\"tables\":"<<s.tables<<",\"bytes\":"<<s.bytes<<",\"records\":"<<s.records<<",\"encoded\":"<<s.encoded<<",\"tombstones\":"<<s.tombstones<<",\"flushed\":"<<s.flushed<<",\"physical\":"<<s.physical<<"}";}
long rss(){rusage u{};getrusage(RUSAGE_SELF,&u);return u.ru_maxrss;}
void prewarm(const std::string& d){auto mf=Manifest::Load(d+"/MANIFEST");for(const auto& t:mf.Tables()){SSTableReader r(path(d,t.fileNumber));for(auto it=r.Begin();it.Valid();it.Next()){} }}
void create(const std::string& d,size_t n,size_t tables,bool multi){need(!fs::exists(d),"fixture exists");auto o=options(0);o.memTableSizeLimit=1024ULL*1024*1024;DB db(d,o);Oracle m;uint64_t seq=0;std::mt19937_64 rng(20261115);size_t versions=multi?4:1;need(tables%versions==0&&n%(tables/versions)==0,"fixture dimensions");size_t shards=tables/versions;for(size_t v=0;v<versions;++v){std::vector<size_t> ids(n);std::iota(ids.begin(),ids.end(),0);std::shuffle(ids.begin(),ids.end(),rng);for(size_t t=0;t<shards;++t){WriteBatch b;for(size_t j=t*(n/shards);j<(t+1)*(n/shards);++j){auto i=ids[j];auto k=key(i);bool del=multi&&v==versions-1&&i%5==0;auto val=del?std::string{}:value(i,v);if(del)b.Delete(k);else b.Put(k,val);m[k]={{k,++seq,del?ValueType::kDeletion:ValueType::kValue},val};}db.Write(b);db.Flush();}}verify(db,m);saveOracle(d,m);need(Manifest::Load(d+"/MANIFEST").Tables().size()==tables,"wrong fixture table count");}
struct Sample{double start=0,elapsed=0;};
void emitLatency(const std::string& name,const std::vector<Sample>& a,double wall,const std::string& file){std::vector<double> v;v.reserve(a.size());for(auto x:a)v.push_back(x.elapsed);std::sort(v.begin(),v.end());auto pct=[&](double p){return v.empty()?0:v[std::min(v.size()-1,size_t(p*(v.size()-1)))];};std::ofstream f(file);f<<"start_ns,elapsed_ns\n"<<std::setprecision(17);for(auto x:a)f<<x.start<<","<<x.elapsed<<"\n";std::cout<<"{\"case\":\""<<name<<"\",\"count\":"<<a.size()<<",\"wall_ns\":"<<wall<<",\"ops_s\":"<<(wall>0?a.size()*1e9/wall:0)<<",\"p50_ns\":"<<pct(.5)<<",\"p95_ns\":"<<pct(.95)<<",\"p99_ns\":"<<pct(.99)<<",\"max_ns\":"<<(v.empty()?0:v.back())<<"}";}
void compact(const std::string& d,bool run,size_t target){auto m=loadOracle(d);auto before=stats(d,m,false);auto db=std::make_unique<DB>(d,options(0,target));auto a=Clock::now();if(run)db->Compact();auto b=Clock::now();db.reset();auto c=Clock::now();long peak=rss();auto after=stats(d,m,run);need(before.flushed==after.flushed,"flushed advanced on compact");need(after.physical==after.tables,"unclean old sst");{DB reopened(d,options(0));verify(reopened,m);}std::cout<<"{\"mode\":\"compact\",\"run\":"<<run<<",\"target\":"<<target<<",\"api_ns\":"<<ns(a,b)<<",\"close_ns\":"<<ns(b,c)<<",\"total_ns\":"<<ns(a,c)<<",\"rss_kib\":"<<peak<<",\"before\":";emitStats(before);std::cout<<",\"after\":";emitStats(after);std::cout<<",\"verified\":true}\n";}
void query(const std::string& d,size_t cap,size_t count,const std::string& out){auto m=loadOracle(d);std::vector<std::string> live,dead;for(auto& p:m)(p.second.key.type==ValueType::kValue?live:dead).push_back(p.first);prewarm(d);std::cout<<"{\"mode\":\"query\",\"capacity\":"<<cap<<",\"cases\":[";bool first=true;for(const std::string name:{"uniform","hot","missing","deleted"}){if(name=="deleted"&&dead.empty())continue;std::mt19937_64 rng(20261115);std::vector<std::string> trace;trace.reserve(count);for(size_t i=0;i<count;++i){if(name=="missing"){auto k=key(rng()%m.size());k.back()=(k.back()=='e'?'f':char(k.back()+1));trace.push_back(k);}else{auto& keys=name=="deleted"?dead:live;trace.push_back(keys[rng()%(name=="hot"?std::min<size_t>(32,keys.size()):keys.size())]);}}auto db=std::make_unique<DB>(d,options(cap));std::vector<std::optional<std::string>> results(count);std::vector<Sample> samples(count);for(int pass=0;pass<2;++pass){auto start=Clock::now();for(size_t i=0;i<count;++i){auto a=Clock::now();results[i]=db->Get(trace[i]);auto b=Clock::now();samples[i]={ns(start,a),ns(a,b)};}auto end=Clock::now();for(size_t i=0;i<count;++i){auto p=m.find(trace[i]);bool found=p!=m.end()&&p->second.key.type==ValueType::kValue;need(bool(results[i])==found,"trace existence");if(found)need(*results[i]==p->second.value,"trace value");}if(!first)std::cout<<",";first=false;emitLatency(name+"-"+std::to_string(pass),samples,ns(start,end),out+"-"+name+"-"+std::to_string(pass)+".csv");}db.reset();}std::cout<<"],\"rss_kib\":"<<rss()<<",\"verified\":true}\n";}
void impact(const std::string& d,bool run,bool writing,size_t count,const std::string& out,double controlNs){auto m=loadOracle(d);prewarm(d);auto db=std::make_unique<DB>(d,options(0));std::vector<std::string> keys;for(auto& p:m)if(p.second.key.type==ValueType::kValue)keys.push_back(p.first);std::mt19937_64 rng(20261115);std::vector<size_t> trace(count);for(auto& i:trace)i=rng()%keys.size();std::vector<WriteBatch> batches;size_t batchSize=64;if(writing){batches.resize(count);for(size_t i=0;i<count;++i)for(size_t j=0;j<batchSize;++j){auto k=key(1000000+i*batchSize+j);auto v=value(i*batchSize+j,7);batches[i].Put(k,v);m[k]={{k,0,ValueType::kValue},v};}}std::vector<std::optional<std::string>> readResults(writing?0:count);std::vector<Sample> samples(count);std::atomic<size_t> done{0};std::atomic<bool> go{false};std::exception_ptr error;Clock::time_point begin,end;double flushNs=0;std::thread worker([&]{try{while(!go.load())std::this_thread::yield();begin=Clock::now();for(size_t i=0;i<count;++i){auto a=Clock::now();if(writing)db->Write(batches[i]);else readResults[i]=db->Get(keys[trace[i]]);auto b=Clock::now();samples[i]={ns(begin,a),ns(a,b)};done.store(i+1);}end=Clock::now();if(writing){auto f=Clock::now();db->Flush();flushNs=ns(f,Clock::now());}}catch(...){error=std::current_exception();done=count;}});auto totalStart=Clock::now();go=true;while(done.load()<std::min<size_t>(writing?4:512,count))std::this_thread::yield();auto ca=Clock::now();if(run)db->Compact();else std::this_thread::sleep_for(std::chrono::nanoseconds(static_cast<long long>(controlNs)));auto cb=Clock::now();worker.join();if(error)std::rethrow_exception(error);auto close=Clock::now();db.reset();auto closed=Clock::now();long peak=rss();if(!writing)for(size_t i=0;i<count;++i)need(readResults[i]&&*readResults[i]==m.at(keys[trace[i]]).value,"concurrent trace mismatch");{DB reopen(d,options(0));verify(reopen,m);}std::cout<<"{\"mode\":\"impact\",\"writing\":"<<writing<<",\"run\":"<<run<<",\"wal\":false,\"batch\":"<<(writing?batchSize:1)<<",\"window_start_ns\":"<<ns(begin,ca)<<",\"window_end_ns\":"<<ns(begin,cb)<<",\"compact_window_ns\":"<<ns(ca,cb)<<",\"flush_ns\":"<<flushNs<<",\"close_ns\":"<<ns(close,closed)<<",\"total_ns\":"<<ns(totalStart,closed)<<",\"rss_kib\":"<<peak<<",\"requests\":";emitLatency("all",samples,ns(begin,end),out+"-timeline.csv");std::cout<<",\"verified\":true}\n";}
